<script setup>
import { onMounted,ref } from 'vue'; import {useRoute,useRouter} from 'vue-router'; import RepairmentForm from '@/features/repairment-form/RepairmentForm.vue'; import FeedbackMessage from '@/components/FeedbackMessage.vue'; import {apiRequest} from '@/lib/api'; const route=useRoute(),router=useRouter(),repairment=ref(null),error=ref(''),busy=ref(false); onMounted(async()=>{try{repairment.value=await apiRequest(`/api/repairments/${route.params.id}`)}catch(e){error.value=e.message}}); async function save(form){busy.value=true;try{await apiRequest(`/api/repairments/${route.params.id}`,{method:'PATCH',body:JSON.stringify(form)});await router.push(`/repairments/${route.params.id}`)}catch(e){error.value=e.message}finally{busy.value=false}}
</script>
<template><main class="page editor-page"><RouterLink class="back-link" :to="`/repairments/${route.params.id}`">← Repairment details</RouterLink><span class="eyebrow eyebrow--light">Edit repairment</span><h1>Update repairment progress.</h1><FeedbackMessage :message="error" /><RepairmentForm v-if="repairment" :initial-repairment="repairment" :busy="busy" submit-label="Update repairment" @submit="save" /></main></template>
